export const relationships={
 amor:{label:'Meu amor',counter:'Juntos há',date:'Quando tudo começou'},mae:{label:'Mãe',counter:'Sendo minha mãe há',date:'Uma data da nossa história'},pai:{label:'Pai',counter:'Sendo meu pai há',date:'Uma data da nossa história'},avos:{label:'Avós',counter:'Me mimando há',date:'Uma data da nossa história'},amigo:{label:'Amigos',counter:'Amizade há',date:'Quando vocês se conheceram'},filho:{label:'Filho ou filha',counter:'Iluminando minha vida há',date:'Data de nascimento'},pet:{label:'Meu pet',counter:'Bagunçando a casa há',date:'Quando chegou em casa'},outro:{label:'Alguém especial',counter:'Desde aquele dia',date:'Uma data especial'}
};
const text=(value,max)=>typeof value==='string'?value.slice(0,max):'';
export function validDate(value){if(!/^\d{4}-\d{2}-\d{2}$/.test(value??''))return false;const date=new Date(value+'T12:00:00Z');return Number.isFinite(date.getTime())&&date.toISOString().slice(0,10)===value;}
export function cleanExperience(value={}){const v=value&&typeof value==='object'?value:{};return {audioKind:v.audioKind==='music'?'music':'voice',audioVolume:Number.isFinite(Number(v.audioVolume))?Math.max(0,Math.min(1,Number(v.audioVolume))):.6,audioLoop:typeof v.audioLoop==='boolean'?v.audioLoop:v.audioKind==='music',relationship:Object.hasOwn(relationships,v.relationship)?v.relationship:'amor',sender:text(v.sender,60),specialDate:validDate(v.specialDate)?v.specialDate:'',city:text(v.city,100),letter:text(v.letter,2000),sound:['musicbox','file','link','off'].includes(v.sound)?v.sound:'musicbox',musicUrl:safeMusicURL(v.musicUrl),audioName:text(v.audioName,100),counter:v.counter!==false,sky:!!v.sky,timeline:Array.isArray(v.timeline)?v.timeline.slice(0,12).map(row=>({when:text(row?.when,40),message:text(row?.message,240)})):[],wheel:Array.isArray(v.wheel)?v.wheel.slice(0,12).map(item=>text(item,80)):[],secret:{hint:text(v.secret?.hint,180),answer:text(v.secret?.answer,100),message:text(v.secret?.message,1000)},openWhen:Array.isArray(v.openWhen)?v.openWhen.slice(0,8).map(row=>({title:text(row?.title,100),message:text(row?.message,1000)})):[],reply:v.reply!==false,collective:Array.isArray(v.collective)?v.collective.slice(0,30).map(row=>({id:text(row?.id,60)||crypto.randomUUID(),name:text(row?.name,60),message:text(row?.message,1000)})):[]};}
export function safeMusicURL(value){try{const url=new URL(value);return url.protocol==='https:'&&['www.youtube.com','youtube.com','youtu.be','open.spotify.com','music.youtube.com'].includes(url.hostname)?url.href:'';}catch{return '';}}
export function calendarSpan(from,to=new Date()){
 if(!validDate(from))return null;const [y,m,d]=from.split('-').map(Number),today=Date.UTC(to.getFullYear(),to.getMonth(),to.getDate()),start=Date.UTC(y,m-1,d);
 if(start>today)return {future:true,days:Math.ceil((start-today)/86400000),years:0,months:0,hours:0,minutes:0,seconds:0};
 const addMonths=count=>{const month=m-1+count,year=y+Math.floor(month/12),normal=((month%12)+12)%12;return Date.UTC(year,normal,Math.min(d,new Date(Date.UTC(year,normal+1,0)).getUTCDate()));};
 let totalMonths=(to.getFullYear()-y)*12+to.getMonth()-(m-1);if(addMonths(totalMonths)>today)totalMonths--;const days=Math.round((today-addMonths(totalMonths))/86400000),elapsed=Math.max(0,Math.floor((to.getTime()-new Date(y,m-1,d).getTime())/1000));
 return {future:false,years:Math.floor(totalMonths/12),months:totalMonths%12,days,hours:Math.floor(elapsed/3600)%24,minutes:Math.floor(elapsed/60)%60,seconds:elapsed%60};
}
export function approximateMoon(date){const instant=validDate(date)?Date.parse(date+'T21:00:00Z'):Date.now(),period=29.530588853;const age=((instant-Date.UTC(2000,0,6,18,14))/86400000%period+period)%period;const names=['Lua nova','Crescente','Quarto crescente','Crescente gibosa','Lua cheia','Minguante gibosa','Quarto minguante','Minguante'];return {phase:age/period,name:names[Math.floor((age/period*8+.5)%8)],illumination:Math.round((1-Math.cos(2*Math.PI*age/period))/2*100)};}
export const node=(tag,className,text)=>{const e=document.createElement(tag);if(className)e.className=className;if(text!==undefined)e.textContent=text;return e;};
const folded=value=>value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim().toLocaleLowerCase('pt-BR').replace(/\s+/g,' ');
export function paintSky(canvas,date,city=''){const ctx=canvas.getContext('2d');canvas.width=900;canvas.height=500;ctx.fillStyle='#193754';ctx.fillRect(0,0,900,500);let seed=2166136261;for(const c of date+city)seed=Math.imul(seed^c.charCodeAt(0),16777619);const random=()=>{seed^=seed<<13;seed^=seed>>>17;seed^=seed<<5;return (seed>>>0)/4294967296;};for(let i=0;i<100;i++){ctx.globalAlpha=.25+random()*.65;ctx.fillStyle='#fff6ea';ctx.beginPath();ctx.arc(random()*900,random()*500,.7+random()*1.7,0,Math.PI*2);ctx.fill();}ctx.globalAlpha=1;const moon=approximateMoon(date);ctx.fillStyle='#fff3d3';ctx.beginPath();ctx.arc(710,140,48,0,Math.PI*2);ctx.fill();ctx.fillStyle='#193754';ctx.globalAlpha=1-moon.illumination/100;ctx.beginPath();ctx.arc(728,128,46,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;}
export function createExperienceChapters(container,data,{saveReply}={}){
 const ex=cleanExperience(data.experience),cleanups=[];container.replaceChildren();container.classList.add('experience-chapters');
 function section(title,kind=''){const article=node('section','experience-chapter '+kind);article.append(node('h3','',title));container.append(article);return article;}
 if(ex.counter&&ex.specialDate){const area=section(relationships[ex.relationship].counter,'elapsed-chapter'),numbers=node('div','elapsed-numbers'),clock=node('p','elapsed-clock');area.append(numbers,clock);const update=()=>{const span=calendarSpan(ex.specialDate);numbers.replaceChildren();if(span.future){numbers.append(node('strong','',String(span.days)),node('span','','dias para essa data'));clock.textContent='O próximo capítulo está chegando.';}else{for(const [value,label] of [[span.years,'anos'],[span.months,'meses'],[span.days,'dias']]){const part=node('div');part.append(node('strong','',String(value)),node('span','',label));numbers.append(part);}clock.textContent=[span.hours,span.minutes,span.seconds].map(n=>String(n).padStart(2,'0')).join(':');}};update();const timer=setInterval(()=>{if(!document.hidden)update();},1000);cleanups.push(()=>clearInterval(timer));}
 if(ex.sky){const moon=approximateMoon(ex.specialDate),area=section('O céu de um dia especial','sky-chapter'),canvas=node('canvas');canvas.setAttribute('aria-hidden','true');paintSky(canvas,ex.specialDate,ex.city);area.append(canvas,node('p','',moon.name+' · cerca de '+moon.illumination+'% iluminada'),node('small','',([ex.city,ex.specialDate].filter(Boolean).join(' · ')||'Um céu para guardar')+' — ilustração simbólica; fase lunar aproximada.'));}
 if(ex.timeline.some(row=>row.message.trim())){const area=section('A nossa linha do tempo'),list=node('ol','memory-timeline');for(const row of ex.timeline.filter(row=>row.message.trim())){const item=node('li');item.append(node('strong','',row.when),node('p','',row.message));list.append(item);}area.append(list);}
 const wheelItems=ex.wheel.filter(item=>item.trim());if(wheelItems.length>=2){const area=section('Roleta de pequenos planos'),canvas=node('canvas','mimo-wheel'),result=node('p','wheel-result'),button=node('button','button primary','Girar a roleta');button.type='button';result.setAttribute('aria-live','polite');canvas.width=canvas.height=540;area.append(canvas,result,button);const ctx=canvas.getContext('2d'),colors=['#E8473A','#F6B42C','#2F7BE0','#F2557D','#7A567F','#D98A4E'];let rotation=0,raf=0;function draw(){ctx.clearRect(0,0,540,540);const arc=Math.PI*2/wheelItems.length;for(let i=0;i<wheelItems.length;i++){ctx.save();ctx.translate(270,270);ctx.rotate(rotation+i*arc);ctx.beginPath();ctx.moveTo(0,0);ctx.arc(0,0,248,0,arc);ctx.closePath();ctx.fillStyle=colors[i%colors.length];ctx.fill();ctx.strokeStyle='#3a1e14';ctx.lineWidth=3;ctx.stroke();ctx.rotate(arc/2);ctx.fillStyle='#fff';ctx.font='bold 18px sans-serif';ctx.textAlign='right';ctx.fillText(wheelItems[i].length>23?wheelItems[i].slice(0,21)+'…':wheelItems[i],228,7);ctx.restore();}ctx.fillStyle='#3a1e14';ctx.beginPath();ctx.moveTo(264,4);ctx.lineTo(244,42);ctx.lineTo(284,42);ctx.closePath();ctx.fill();}draw();button.addEventListener('click',()=>{button.disabled=true;const value=crypto.getRandomValues(new Uint32Array(1))[0]/4294967296,index=Math.floor(value*wheelItems.length),arc=Math.PI*2/wheelItems.length,start=rotation,desired=-Math.PI/2-(index+.5)*arc;let target=desired;while(target<start+Math.PI*8)target+=Math.PI*2;const begin=performance.now(),duration=matchMedia('(prefers-reduced-motion: reduce)').matches?0:1800;function tick(t){const p=duration?Math.min(1,(t-begin)/duration):1;rotation=start+(target-start)*(1-(1-p)**3);draw();if(p<1)raf=requestAnimationFrame(tick);else{result.textContent=wheelItems[index];button.disabled=false;}}raf=requestAnimationFrame(tick);});cleanups.push(()=>cancelAnimationFrame(raf));}
 if(ex.secret.answer.trim()){const area=section(ex.secret.hint||'Uma pergunta só nossa'),form=node('form','secret-answer'),input=node('input'),button=node('button','button primary','Revelar'),result=node('p','secret-result');input.placeholder='Qual é a resposta?';input.maxLength=100;input.setAttribute('aria-label','Resposta da pergunta');result.setAttribute('aria-live','polite');form.append(input,button);form.addEventListener('submit',event=>{event.preventDefault();result.textContent=folded(input.value)===folded(ex.secret.answer)?ex.secret.message||'Acertou. Essa lembrança é só nossa.':'Ainda não. Tente mais uma vez.';});area.append(form,result);}
 if(ex.openWhen.some(row=>row.title&&row.message)){const area=section('Abra quando…');for(const row of ex.openWhen.filter(row=>row.title&&row.message)){const details=node('details','open-when-letter');details.append(node('summary','',row.title),node('p','',row.message));area.append(details);}}
 if(ex.collective.some(row=>row.message)){const area=section('De quem também te quer bem');for(const row of ex.collective.filter(row=>row.message)){const note=node('article','collective-note');note.append(node('strong','',row.name||'Alguém especial'),node('p','',row.message));area.append(note);}}
 if(ex.letter.trim()){const area=section('Uma carta pra você'),details=node('details','personal-letter'),summary=node('summary','','Abrir minha carta'),envelope=node('img','letter-envelope');envelope.src=data.storyAssets?.envelope||data.portableAssets?.['assets/hero-motion-envelope.webp']||'assets/hero-motion-envelope.webp';envelope.alt='';envelope.width=250;envelope.height=200;summary.prepend(envelope);details.append(summary,node('p','',ex.letter));area.append(details);}
 if(ex.reply){const area=section('O que você sentiu?'),form=node('form','gift-reply'),input=node('textarea'),button=node('button','button primary','Guardar minha resposta'),status=node('p','reply-status');input.maxLength=2000;input.rows=4;input.placeholder='Escreva uma resposta para quem preparou este mimo.';input.setAttribute('aria-label','Sua resposta');input.required=true;button.type='submit';status.setAttribute('role','status');form.append(input,button);form.addEventListener('submit',event=>{event.preventDefault();const response={id:crypto.randomUUID(),giftId:data.giftId||data.draftId||'preview',message:input.value.trim(),createdAt:new Date().toISOString()};if(!response.message)return;saveReply?.(response);try{localStorage.setItem('capimimo-reply-'+response.giftId,JSON.stringify(response));}catch{}status.textContent='Resposta guardada neste aparelho. Baixe o arquivo para devolver a quem criou o presente.';let download=area.querySelector('.download-reply');if(!download){download=node('button','button outline download-reply','Baixar minha resposta');download.type='button';area.append(download);}download.onclick=()=>downloadFile('capimimo-resposta.json',new Blob([JSON.stringify(response,null,2)],{type:'application/json'}));});area.append(form,status);}
 return ()=>cleanups.forEach(cleanup=>cleanup());
}
export function downloadFile(name,blob){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}

// A folded card/invitation has one inside spread, not a hidden book of chapters.
export function giftContentPages(data={}){if(data.format==='livro'&&Array.isArray(data.pages)&&data.pages.length)return data.pages;const photo=Object.hasOwn(data,'coverPhoto')?data.coverPhoto:Object.hasOwn(data,'photo')?data.photo:data.pages?.[0]?.photo;return[{title:data.format==='cartao'?'Sua dedicatória':data.format==='convite'?'Seu convite':data.pageTitle||'Nossa história.',message:data.message??data.pages?.[0]?.message??'',photo:photo??null}];}
